* { 
  box-sizing: border-box; 
}

body {
  margin: 0; 
  padding: 0;
  width: 1280px; 
  height: 800px;
  background: linear-gradient(135deg, #89f7fe 0%, #66a6ff 100%);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  display: flex;
  justify-content: center;
  align-items: center;
  overflow: hidden;
}

.card {
  background: rgba(255, 255, 255, 0.95);
  backdrop-filter: blur(20px);
  width: 1160px;
  border-radius: 32px;
  box-shadow: 0 25px 60px rgba(0,0,0,0.15);
  padding: 60px;
  display: none;
  flex-direction: column;
  gap: 50px;
}

.message-card {
  background: rgba(255, 255, 255, 0.95);
  width: 600px;
  border-radius: 24px;
  padding: 50px;
  text-align: center;
  box-shadow: 0 20px 50px rgba(0,0,0,0.15);
  font-size: 28px;
  font-weight: 600;
}

.loading {
  color: #4a5568;
}

.error {
  color: #e53e3e;
  display: none;
}

.header {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  border-bottom: 2px solid rgba(0,0,0,0.06);
  padding-bottom: 40px;
}

.location-info h1 {
  margin: 0;
  font-size: 56px;
  color: #1a202c;
  letter-spacing: -1.5px;
}

.location-info p {
  margin: 12px 0 0 0;
  font-size: 26px;
  color: #718096;
  font-weight: 500;
}

.weather-main {
  text-align: right;
}

.weather-main .temps {
  font-size: 48px;
  font-weight: 700;
  color: #2d3748;
  display: flex;
  gap: 20px;
  justify-content: flex-end;
}

.weather-main .temps .min-temp {
  color: #a0aec0;
}

.weather-main .condition {
  margin-top: 12px;
  font-size: 28px;
  color: #4a5568;
  font-weight: 600;
}

.hourly-wrapper {
  width: 100%;
}

.hourly-title {
  font-size: 22px;
  font-weight: 700;
  color: #4a5568;
  margin-bottom: 25px;
  text-transform: uppercase;
  letter-spacing: 1.5px;
}

.hourly-grid {
  display: flex;
  justify-content: space-between;
  width: 100%;
}

.hour-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 14px;
  flex: 1;
}

.hour-time {
  font-size: 16px;
  color: #718096;
  font-weight: 600;
}

.hour-temp {
  font-size: 20px;
  color: #1a202c;
  font-weight: 700;
  background: #edf2f7;
  padding: 10px 0;
  width: 100%;
  text-align: center;
  border-radius: 14px;
}

(function() {
  const params = new URLSearchParams(window.location.search);
  const lat = params.get('lat') || '52.52';
  const lon = params.get('lon') || '13.405';
  const name = params.get('name') || 'Berlin';

  const now = new Date();
  const yyyy = now.getUTCFullYear();
  const mm = String(now.getUTCMonth() + 1).padStart(2, '0');
  const dd = String(now.getUTCDate()).padStart(2, '0');
  const todayStr = `${yyyy}-${mm}-${dd}`;

  const date = params.get('date') || todayStr;
  const isPast = date < todayStr;
  const endpoint = isPast ? '/api/om/archive' : '/api/om/forecast';

  const url = `${endpoint}?latitude=${lat}&longitude=${lon}&daily=temperature_2m_max,temperature_2m_min,weather_code&hourly=temperature_2m&timezone=UTC&temperature_unit=celsius&start_date=${date}&end_date=${date}`;

  const wmo = {
    0: 'Clear sky',
    1: 'Mainly clear', 2: 'Partly cloudy', 3: 'Overcast',
    45: 'Fog', 48: 'Depositing rime fog',
    51: 'Light drizzle', 53: 'Moderate drizzle', 55: 'Dense drizzle',
    56: 'Light freezing drizzle', 57: 'Dense freezing drizzle',
    61: 'Slight rain', 63: 'Moderate rain', 65: 'Heavy rain',
    66: 'Light freezing rain', 67: 'Heavy freezing rain',
    71: 'Slight snow fall', 73: 'Moderate snow fall', 75: 'Heavy snow fall',
    77: 'Snow grains',
    80: 'Slight rain showers', 81: 'Moderate rain showers', 82: 'Violent rain showers',
    85: 'Slight snow showers', 86: 'Heavy snow showers',
    95: 'Thunderstorm', 96: 'Thunderstorm with slight hail', 99: 'Thunderstorm with heavy hail'
  };

  function showError(msg) {
    document.getElementById('loading').style.display = 'none';
    const errCard = document.getElementById('error-card');
    errCard.style.display = 'block';
    errCard.textContent = msg;
  }

  fetch(url)
    .then(res => {
      if (!res.ok) throw new Error('Network response was not ok');
      return res.json();
    })
    .then(data => {
      if (!data.daily || !data.hourly) throw new Error('Invalid data format');

      const maxTemp = data.daily.temperature_2m_max[0];
      const minTemp = data.daily.temperature_2m_min[0];
      const code = data.daily.weather_code[0];
      const hourlyTemps = data.hourly.temperature_2m;

      if (maxTemp === undefined || minTemp === undefined || !hourlyTemps) {
        throw new Error('Missing weather data for this date');
      }

      document.getElementById('loc-name').textContent = name;

      const dateParts = date.split('-');
      const dateObj = new Date(Date.UTC(dateParts[0], dateParts[1] - 1, dateParts[2]));
      const dateStr = dateObj.toLocaleDateString(undefined, { 
        weekday: 'long', 
        year: 'numeric', 
        month: 'long', 
        day: 'numeric', 
        timeZone: 'UTC' 
      });
      document.getElementById('loc-date').textContent = dateStr;

      document.getElementById('temp-max').textContent = `H: ${Math.round(maxTemp)}°C`;
      document.getElementById('temp-min').textContent = `L: ${Math.round(minTemp)}°C`;
      document.getElementById('weather-desc').textContent = wmo[code] !== undefined ? wmo[code] : 'Unknown conditions';

      const grid = document.getElementById('hourly-grid');
      for (let i = 0; i < 24; i++) {
        const temp = hourlyTemps[i];
        const tempText = (temp !== null && temp !== undefined) ? `${Math.round(temp)}°` : '--';

        const item = document.createElement('div');
        item.className = 'hour-item';

        const timeDiv = document.createElement('div');
        timeDiv.className = 'hour-time';
        timeDiv.textContent = `${i.toString().padStart(2, '0')}`;

        const tempDiv = document.createElement('div');
        tempDiv.className = 'hour-temp';
        tempDiv.textContent = tempText;

        item.appendChild(timeDiv);
        item.appendChild(tempDiv);
        grid.appendChild(item);
      }

      document.getElementById('loading').style.display = 'none';
      document.getElementById('weather-card').style.display = 'flex';
    })
    .catch(err => {
      console.error(err);
      showError('Could not load weather data.');
    });
})();
